def test_tc_req_pwr_002_01_v2(bench):
    """TC-REQ-PWR-002-01-v2: IGN 1 -> 0.
    Oracle (REQ-PWR-002): "When IGN changes from ON to OFF, the cluster shall display the goodbye screen for 5 s and then enter the SLEEP state."
    Expected: ClusterState = 2 within 300 ms.
    Why these values: The triggering change from the requirement.
    Open value: reaction time not stated; cases allow 300 ms (two status cycles plus one input cycle)
    """
    bench.set('IGN', 1.0)
    bench.wait_ms(500)
    bench.set('IGN', 0.0)
    assert bench.expect_within('ClusterState', 2.0, 300)


def test_tc_req_pwr_002_02_v2(bench):
    """TC-REQ-PWR-002-02-v2: ClusterState holds for 5000 ms.
    Oracle (REQ-PWR-002): "When IGN changes from ON to OFF, the cluster shall display the goodbye screen for 5 s and then enter the SLEEP state."
    Expected: ClusterState = 2 for 5000 ms, then ends.
    Why these values: Duration from the requirement; checked to one 100 ms status cycle.
    Open value: reaction time not stated; cases allow 300 ms (two status cycles plus one input cycle)
    """
    bench.set('IGN', 1.0)
    bench.wait_ms(500)
    bench.set('IGN', 0.0)
    bench.wait_ms(300)
    assert bench.expect_for('ClusterState', 2.0, 4600)


